func buildCloudLogAnalyticsSetExportConfig() *cobra.Command {
	var arg_regionCode string
	var bodyFile, bodyInline string
	c := &cobra.Command{
		Use: "set-export-config",
		Short: "자동 내보내기 설정",
		Long: "Classic/VPC 환경에서 이용 가능합니다.",
		RunE: func(c *cobra.Command, _ []string) error {
			cfg, err := clicmd.ConfigFromCtx(c)
			if err != nil { return err }
			client, err := cloud_log_analytics.NewFromConfig(cfg)
			if err != nil { return err }
			var body io.Reader
			if bodyFile != "" {
				f, ferr := os.Open(bodyFile)
				if ferr != nil { return fmt.Errorf("open --body-file: %w", ferr) }
				defer f.Close()
				body = f
			} else if bodyInline != "" {
				body = bytes.NewBufferString(bodyInline)
			}
			resp, err := client.SetExportConfigWithBodyWithResponse(c.Context(), arg_regionCode, "application/json", body)
			if err != nil { return err }
			if apiErr := ncloud.AsAPIError(resp.HTTPResponse, resp.Body); apiErr != nil {
				return apiErr
			}
			return clicmd.Render(c.OutOrStdout(), pickPayload(resp))
		},
	}
	c.Flags().StringVar(&arg_regionCode, "regionCode", "", "[PATH] 리전 코드 kr | sgn | jpn | uswn | den kr : 한국 리전 sgn : 싱가포르 리전 jpn : 일본 리전 uswn : 미국 서부 리전 den : 독일 리전")
	_ = c.MarkFlagRequired("regionCode")
	c.Flags().StringVar(&bodyFile, "body-file", "", "Path to a JSON file containing the request body.")
	c.Flags().StringVar(&bodyInline, "body", "", "Inline JSON request body (alternative to --body-file).")
	return c
}
